async function loadJsonCached(path){if(state.dataCache.has(path))return state.dataCache.get(path);state.researchRuns.set(path,(state.researchRuns.get(path)||0)+1);const response=await fetch(path);if(!response.ok)throw new Error(`Unable to load ${path}`);const data=await response.json();state.dataCache.set(path,data);return data;}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function setText(id,value){document.querySelector(`#${id}`).textContent=value||researchNeeded;}
function badge(status){return `<span class="badge ${statusClass(status)}">${escapeHtml(status)}</span>`;}
async function resolveFixture(query){if(!state.fixtures)state.fixtures=await loadJsonCached('data/geography-resolver-fixtures.json');const normalized=query.trim().toLowerCase().replace(/,\s*/g,' ');return state.fixtures.fixtures.find((fixture)=>fixture.match.includes(normalized))||null;}

const pinehavenOnlySelectors=['#profile','#geography-resolver','#community-intelligence','.system-layers','#scorecard','.research-dashboard','#pathway','#hub','#opportunities','#legacy','#sources'];
function setViewMode(isLive){els.quickView.hidden=!isLive;if(!isLive)els.americusProfile.hidden=true;pinehavenOnlySelectors.forEach((selector)=>{const node=document.querySelector(selector);if(node)node.hidden=isLive;});}
function normalizeQuery(value){return String(value||'').trim().toLowerCase().replace(/,\s*/g,' ').replace(/\s+/g,' ');}
function sourceSearchUrl(base,query){return `${base}${base.includes('?')?'&':'?'}search=${encodeURIComponent(query)}`;}
function setPublicRoute(query,isAmericus=false){document.documentElement.classList.toggle('case-route',isAmericus);const url=new URL(window.location.href);if(query)url.searchParams.set('location',query);else url.searchParams.delete('location');window.history.replaceState({},'',url);}

async function loadQuickViewResources(){
  const [zipIndex,quickRegistry,sourceConnectors,smokeTests]=await Promise.all([
    loadJsonCached('data/georgia-zip-index.json'),
    loadJsonCached('data/quick-view-registry.json?v=20260913.5'),
    loadJsonCached('data/source-connectors.json?v=20260913.5'),
    loadJsonCached('data/generic-zip-smoke-tests.json?v=20260913.1')
  ]);
  state.zipIndex=zipIndex;state.quickRegistry=quickRegistry;state.sourceConnectors=sourceConnectors;state.smokeTests=smokeTests;
}

function smokeGeorgiaQuickView(query,rows,smoke){
  const data=genericGeorgiaQuickView(query,rows);const institutionSources=smoke.sources.map((url,index)=>({id:`smoke-${smoke.zip}-${index+1}`,title:smoke.source_types[index]||'Official public source',publisher:new URL(url).hostname.replace(/^www\./,''),type:'Official source lane',date:'Current public path',retrieval_date:'2026-09-13',url}));
  data.status='PRELIMINARY';data.research_status='CACHED';data.smoke_test_only=true;data.sources=institutionSources;data.unknowns=smoke.limitations;
  data.financial_baseline=smoke.populated_categories.includes('municipal finance')||smoke.populated_categories.includes('school finance')?[{entity:data.community.municipality,latest_audited_period:'Latest source linked in bounded smoke test',current_public_signal:'Financial source lane populated; no audit analysis performed',status:'VERIFIED'}]:[];
  data.fiscal_measures=smoke.populated_categories.includes('public capital')?[{type:'Public capital',role:'Official source index located',detail:'A public-capital source lane is available; measure-level validation was outside this smoke test.',categories:['Public investment'],status:'VERIFIED',source_type:'Official'}]:[];
  data.operating_revenue=[];
  data.enterprise_funds=smoke.populated_categories.some((item)=>/utilit|water|energy/.test(item))?[{name:'Public utility context located',accounting_boundary:'Provider and service remain address-specific',detail:'The bounded test located a public utility source. It does not establish project-specific capacity.',status:'VERIFIED'}]:[];
  data.schools_youth=[{title:smoke.school_district,detail:'Official school-system lane resolved; address assignment and detailed outcomes require the appropriate school source.',status:'VERIFIED'}];
  data.assets=smoke.populated_categories.filter((item)=>/education|economic development|workforce/.test(item)).map((item)=>({title:item.replace(/\b\w/g,(char)=>char.toUpperCase()),detail:'An official institutional source was located in the bounded retrieval check.',status:'VERIFIED'}));
  data.recent_signals=[];
  data.community_conditions=smoke.populated_categories.slice(0,5).map((category,index)=>({condition_id:`${smoke.zip}-${index+1}`,category,title:category.replace(/\b\w/g,(char)=>char.toUpperCase()),description:'A useful official source lane is available for deeper current-record extraction.',status:'VERIFIED',source_ids:[institutionSources[Math.min(index,institutionSources.length-1)].id]}));
  data.opportunities=[{title:'Retrieval architecture verified',condition:`${smoke.source_count} bounded public-source lanes connected for ${smoke.resolved_jurisdiction}.`,connection:'A normal research run would extract current conditions and funding before generating any opportunity recommendation.',status:'INFERENCE'}];
  data.entity_cache=institutionSources.map((source)=>({key:`${data.community.county.toLowerCase().replace(/\W+/g,'_')}:public_source:current:${source.id}`,source_id:source.id}));
  return data;
}

