    geography_resolution:{search_geography:query,municipalities:[place],county,zip_codes:related.length?related:[primary.zip],utility_service_areas:['Address-level electric, water, sewer, gas and broadband validation required'],school_districts:[`${county} public-school assignment requires official validation`],development_authorities:[`${county} and municipal authority relationships require validation`],rail_corridors:['Research Needed'],tags:['Georgia Postal Discovery','County Relationship','Service Areas Require Verification']},
    entities:[{entity_id:county.toLowerCase().replace(/\W+/g,'_'),name:`${county} Government`,role:'County government target',status:'NEW_RESEARCH_REQUIRED'},{entity_id:place.toLowerCase().replace(/\W+/g,'_'),name:place,role:'Municipal government target where incorporated',status:'NEW_RESEARCH_REQUIRED'}],
    financial_baseline:[{entity:county,latest_audited_period:'RESEARCH NEEDED',current_public_signal:'Official audit, DCA finance and budget paths prepared',status:'RESEARCH NEEDED'},{entity:place,latest_audited_period:'RESEARCH NEEDED',current_public_signal:'Municipal incorporation and financial-source validation required',status:'RESEARCH NEEDED'},{entity:`${county} school system`,latest_audited_period:'RESEARCH NEEDED',current_public_signal:'GaDOE and DOAA discovery paths prepared',status:'RESEARCH NEEDED'}],
    fiscal_measures:[['SPLOST','Capital projects'],['E-SPLOST','School capital'],['T-SPLOST / TIA','Transportation capital'],['LOST','Operating revenue'],['Bonds','Debt-financed capital']].map(([type,role])=>({type,role,detail:'Discovery path prepared; official measure validation not yet complete.',categories:['RESEARCH NEEDED'],status:'RESEARCH NEEDED',source_type:type==='LOST'?'Audit':'Ballot Measure'})),
    operating_revenue:[{name:'LOST and property taxes',detail:'Current revenue mix requires the latest audit and DCA reporting.',status:'RESEARCH NEEDED'},{name:'Enterprise utilities',detail:'Any proprietary activity must remain separate from ordinary General Fund revenue.',status:'RESEARCH NEEDED'}],
    enterprise_funds:[{name:'Water, sewer, gas, electric, sanitation or broadband enterprises',accounting_boundary:'Proprietary activity — not ordinary General Fund revenue',detail:'Provider, finances, rates, debt, reserves, transfers and capital plans require entity-level research.',status:'RESEARCH NEEDED'}],
    infrastructure_projects:[],recent_signals:[{category:'Government',date:'On demand',title:'Official current-signal search prepared',summary:'The quick view resolved Georgia geography; current official and local-publication retrieval remains incomplete.',status:'RESEARCH NEEDED',source_type:'Official'}],
