async function resolveGeorgiaQuickView(query){
  await loadQuickViewResources();const normalized=normalizeQuery(query);const numeric=/^\d{5}$/.test(normalized);
  const profile=state.quickRegistry.profiles.find((item)=>item.match.includes(normalized));
  if(profile){const result=structuredClone(profile);result.geography_resolution.search_geography=query;return {data:result};}
  let rows=[];
  if(numeric)rows=state.zipIndex.zips.filter((row)=>row.zip===normalized);
  else rows=state.zipIndex.zips.filter((row)=>normalizeQuery(row.place)===normalized||normalizeQuery(row.county)===normalized||normalizeQuery(`${row.county} georgia`)===normalized);
  if(!rows.length)return {error:numeric?'Community Forward Georgia currently analyzes Georgia communities only.':'No Georgia ZIP, city, or county match was found. Try a five-digit Georgia ZIP code.'};
  const smoke=numeric?state.smokeTests.tests.find((item)=>item.zip===normalized):null;
  if(smoke)return {data:smokeGeorgiaQuickView(query,rows,smoke)};
  return {data:genericGeorgiaQuickView(query,rows)};
}

