  const conditions=data.community_conditions?.length?data.community_conditions:(data.recent_signals||[]).slice(0,6).map((item,index)=>({condition_id:`signal-${index}`,category:item.category,title:item.title,description:item.summary,status:item.status,source_ids:[]}));
  renderQuickItems(els.quickConditions,conditions,(item)=>`<div class="signal-item"><span class="signal-category">${escapeHtml(item.category)}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.description||item.short_description)}</p>${item.source_ids?.length?`<small>Sources: ${item.source_ids.map(escapeHtml).join(' · ')}</small>`:''}</div>${badge(item.status||item.evidence_status)}</div>`);
  renderQuickItems(els.quickSignals,data.recent_signals,(item)=>`<div class="signal-item"><span class="signal-category">${escapeHtml(item.category)}</span><div><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.date)} · ${escapeHtml(item.source_type)}</small><p>${escapeHtml(item.summary)}</p></div>${badge(item.status)}</div>`);
  renderQuickItems(els.quickSchools,data.schools_youth,(item)=>`<div class="quick-item"><strong>${escapeHtml(item.title)}</strong>${badge(item.status)}<p>${escapeHtml(item.detail)}</p></div>`);
